const rows = $input.all();
const config = {};
for (const row of rows) {
  config[row.json.campo] = row.json.valor;
}

const {
  numero_admin = '',
  correo_admin = '',
  grupo_whatsapp = '',
  modo_prueba = 'false',
  horario_inicio = '10:00:00',
  horario_fin = '17:00:00',
  duracion_reunion = '30',
  nombre_agente = 'Zura',
  nombre_empresa = 'ZURA Solutions'
} = config;

// Construir businessInfo con campos dinámicos
const RESERVADOS = new Set(['numero_admin','correo_admin','grupo_whatsapp','modo_prueba','horario_inicio','horario_fin','duracion_reunion','nombre_agente','nombre_empresa']);
const parts = [];
for (const [key, val] of Object.entries(config)) {
  if (!RESERVADOS.has(key) && val) parts.push(`${key}: ${val}`);
}
const businessInfo = parts.join('\n');

return [{ json: { ...config, businessInfo, numero_admin, correo_admin, grupo_whatsapp, modo_prueba, horario_inicio, horario_fin, duracion_reunion, nombre_agente, nombre_empresa }, pairedItem: { item: 0 } }];

const fechaDesde = $fromAI('fecha_desde', 'Fecha inicio búsqueda YYYY-MM-DD', 'string');
const fechaHasta = $fromAI('fecha_hasta', 'Fecha fin búsqueda YYYY-MM-DD', 'string');
const horaInicioStr = $fromAI('hora_inicio', 'Hora inicio en formato HH:MM, default 10:00', 'string') || '10:00';
const horaFinStr = $fromAI('hora_fin', 'Hora fin en formato HH:MM, default 17:00', 'string') || '17:00';
const duracionMin = parseInt($fromAI('duracion_minutos', 'Duración en minutos, default 30', 'string') || '30');

const [hIni, mIni] = horaInicioStr.split(':').map(Number);
const [hFin, mFin] = horaFinStr.split(':').map(Number);
const ahora = new Date();

const slots = [];
let fecha = new Date(fechaDesde + 'T12:00:00Z');
const limite = new Date(fechaHasta + 'T12:00:00Z');

while (fecha <= limite && slots.length < 10) {
  const dow = fecha.getDay();
  if (dow !== 0 && dow !== 6) {
    for (let h = hIni; h < hFin && slots.length < 10; h++) {
      const mStart = (h === hIni) ? mIni : 0;
      for (let m = mStart; m + duracionMin <= hFin * 60 + mFin && slots.length < 10; m += duracionMin) {
        const slotStr = `${fecha.toISOString().slice(0,10)}T${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:00`;
        const slotDate = new Date(slotStr + '-06:00');
        if (slotDate > ahora) {
          const slotEnd = new Date(slotDate.getTime() + duracionMin * 60000);
          slots.push({
            inicio: slotDate.toISOString(),
            fin: slotEnd.toISOString(),
            display: slotDate.toLocaleString('es-MX', { weekday:'short', month:'short', day:'numeric', hour:'2-digit', minute:'2-digit', timeZone:'America/Mexico_City' })
          });
        }
      }
    }
  }
  fecha.setDate(fecha.getDate() + 1);
}

if (slots.length === 0) return 'No hay horarios disponibles en el rango indicado.';
return 'Horarios disponibles:\n' + slots.map((s, i) => `${i+1}. ${s.display}`).join('\n');

const agentOutput = $input.first().json;
const output = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

const agendarStep   = steps.find(s => s.action?.tool === 'agendar_cita');
const cancelarStep  = steps.find(s => s.action?.tool === 'cancelar_cita');
const reagendarStep = steps.find(s => s.action?.tool === 'agendar_cita' && steps.some(s2 => s2.action?.tool === 'cancelar_cita'));

const googleEventId = agendarStep?.observation?.id || agendarStep?.observation?.event_id || null;
const googleEventIdCancelado = cancelarStep?.observation?.id || null;

let tipoEvento = 'ninguno';
if (googleEventId && googleEventIdCancelado) tipoEvento = 'reagendada';
else if (googleEventId) tipoEvento = 'nueva';
else if (googleEventIdCancelado) tipoEvento = 'cancelada';

return [{
  json: {
    output,
    tipoEvento,
    googleEventId,
    googleEventIdCancelado,
    citaAgendada: agendarStep?.observation || null,
    eventoCancelado: cancelarStep?.observation || null
  },
  pairedItem: { item: 0 }
}];

