const c = $input.first().json;
const nombre = c.nombre_usuario || 'Cliente';
const mensaje = `Hola ${nombre} 👋

Te recordamos que tienes una cita programada:

📅 *Fecha:* ${c.fecha_fmt}
🕐 *Hora:* ${c.hora_fmt}
📋 *Asunto:* ${c.titulo || 'Reunión de consultoría'}

Si necesitas reprogramar o cancelar, responde a este mensaje.

— ZURA Solutions`;
return [{ json: { numero_whatsapp: c.numero_whatsapp, mensaje, cita_id: c.cita_id }, pairedItem: { item: 0 } }];

const evt = $json.body || $json;
const status = evt.status;
let nuevoEstado = null;
if (status === 'cancelled') nuevoEstado = 'cancelada';
else if (status === 'confirmed') nuevoEstado = 'confirmada';
else if (status === 'tentative') nuevoEstado = 'pendiente';
return [{ json: { google_event_id: evt.id, gcal_status: status, nuevo_estado: nuevoEstado, inicio: evt.start?.dateTime || evt.start?.date || null, fin: evt.end?.dateTime || evt.end?.date || null, titulo: evt.summary || null }, pairedItem: { item: 0 } }];

const d = $input.first().json;
const errAlert = parseInt(d.errores_pendientes || 0) > 0 ? `
⚠️ *Errores pendientes:* ${d.errores_pendientes}` : '';
const fecha = new Date().toLocaleDateString('es-MX', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'America/Mexico_City' });
const mensaje = `📊 *Reporte Diario — ZURA Solutions*
🗓 ${fecha}

💬 *Mensajes:* ${d.total_mensajes || 0}
👥 *Usuarios nuevos:* ${d.usuarios_nuevos || 0}
📅 *Citas agendadas:* ${d.citas_agendadas || 0}
✅ *Completadas:* ${d.citas_completadas || 0}
❌ *Canceladas:* ${d.citas_canceladas || 0}
🎯 *Conversión:* ${d.tasa_pct || 0}%
⚡ *T. respuesta:* ${d.tiempo_seg || 0}s
📆 *Citas futuras:* ${d.citas_futuras || 0}${errAlert}`;
return [{ json: { mensaje }, pairedItem: { item: 0 } }];
